import fitz, numpy as np
doc = fitz.open('eprint/figure4.pdf')
page = doc[0]
d = page.get_drawings()

def pts_of(dr):
    pts = []
    for it in dr['items']:
        if it[0] == 'l':
            pts.append((it[1].x, it[1].y)); pts.append((it[2].x, it[2].y))
        elif it[0] == 'c':
            for p in it[1:]:
                pts.append((p.x, p.y))
    return np.array(pts)

for idx, name in [(35,'pink E3/E2'), (36,'blue E3/Sr')]:
    P = pts_of(d[idx])
    print(name, P.shape, 'x range', P[:,0].min(), P[:,0].max(), 'y range', P[:,1].min(), P[:,1].max())
    # distribution of y values
    ys = P[:,1]
    print('  frac y<=26.31:', np.mean(ys<=26.35), 'frac y>=136:', np.mean(ys>=136), 'frac y>=170:', np.mean(ys>=170))
    np.save(f'poly{idx}.npy', P)
